        #[doc(hidden)]
        pub fn __acoustic_analysis_task_task(
            rx: embassy_sync::channel::Receiver<
                'static,
                embassy_sync::blocking_mutex::raw::CriticalSectionRawMutex,
                AcousticFftInput,
                2,
            >,
        ) -> impl ::core::future::Future<Output = ()> {
            async fn __acoustic_analysis_task_task_inner_function(
                rx: embassy_sync::channel::Receiver<
                    'static,
                    embassy_sync::blocking_mutex::raw::CriticalSectionRawMutex,
                    AcousticFftInput,
                    2,
                >,
            ) {
                loop {
                    let received = rx.receive().await;
                    let mut buffer = {
                        let mut buf = [0f32; FFT_SIZE];
                        for (i, &sample) in received.iter().enumerate() {
                            buf[i] = sample as f32;
                        }
                        buf
                    };
                    let result = Audio::analyze_audio(&mut buffer).await;
                    {
                        let mut state = GLOBAL_STATE.lock().await;
                        state.acoustic_data = Some(result);
                    }
                }
            }
            { __acoustic_analysis_task_task_inner_function(rx) }
        }
