fn get_stm_config() -> embassy_stm32::Config {
    let mut config = embassy_stm32::Config::default();
    let dbgmcu = embassy_stm32::pac::DBGMCU;
    dbgmcu
        .cr()
        .modify(|w| {
            w.set_dbgsleep_d1(true);
            w.set_dbgstby_d1(true);
            w.set_dbgstop_d1(true);
        });
    {
        {
            ::core::option::Option::Some("trace");
            match (&(TICK_HZ)) {
                (arg0) => {
                    if {
                        const CHECK: bool = {
                            const fn check() -> bool {
                                let module_path = "aerosmart_firmware".as_bytes();
                                if if 18usize > module_path.len() {
                                    false
                                } else {
                                    module_path[0usize] == 97u8 && module_path[1usize] == 101u8
                                        && module_path[2usize] == 114u8
                                        && module_path[3usize] == 111u8
                                        && module_path[4usize] == 115u8
                                        && module_path[5usize] == 109u8
                                        && module_path[6usize] == 97u8
                                        && module_path[7usize] == 114u8
                                        && module_path[8usize] == 116u8
                                        && module_path[9usize] == 95u8
                                        && module_path[10usize] == 102u8
                                        && module_path[11usize] == 105u8
                                        && module_path[12usize] == 114u8
                                        && module_path[13usize] == 109u8
                                        && module_path[14usize] == 119u8
                                        && module_path[15usize] == 97u8
                                        && module_path[16usize] == 114u8
                                        && module_path[17usize] == 101u8
                                        && if 18usize == module_path.len() {
                                            true
                                        } else {
                                            module_path[18usize] == b':'
                                        }
                                } {
                                    return true;
                                }
                                false
                            }
                            check()
                        };
                        CHECK
                    } {
                        unsafe {
                            defmt::export::acquire_and_header(
                                &{
                                    defmt::export::make_istr({
                                        #[link_section = ".defmt.info.{\"package\":\"aerosmart-firmware\",\"tag\":\"defmt_info\",\"data\":\"The tick frequency is {} Hz\",\"disambiguator\":\"12304632195700825310\",\"crate_name\":\"aerosmart_firmware\"}"]
                                        #[export_name = "{\"package\":\"aerosmart-firmware\",\"tag\":\"defmt_info\",\"data\":\"The tick frequency is {} Hz\",\"disambiguator\":\"12304632195700825310\",\"crate_name\":\"aerosmart_firmware\"}"]
                                        static DEFMT_LOG_STATEMENT: u8 = 0;
                                        &DEFMT_LOG_STATEMENT as *const u8 as u16
                                    })
                                },
                            );
                        };
                        defmt::export::fmt(arg0);
                        unsafe { defmt::export::release() }
                    }
                }
            }
        };
        use embassy_stm32::rcc::*;
        config.rcc.hsi = Some(HSIPrescaler::DIV4);
        config.rcc.hse = Some(Hse {
            freq: Hertz::mhz(400),
            mode: HseMode::Oscillator,
        });
        config.rcc.csi = true;
        config.rcc.hsi48 = Some(Default::default());
        config.rcc.pll1 = Some(Pll {
            source: PllSource::HSI,
            prediv: PllPreDiv::DIV4,
            mul: PllMul::MUL50,
            divp: Some(PllDiv::DIV2),
            divq: Some(PllDiv::DIV1),
            divr: None,
        });
        config.rcc.pll2 = Some(Pll {
            source: PllSource::HSI,
            prediv: PllPreDiv::DIV4,
            mul: PllMul::MUL50,
            divp: Some(PllDiv::DIV8),
            divq: None,
            divr: None,
        });
        config.rcc.sys = Sysclk::PLL1_P;
        config.rcc.ahb_pre = AHBPrescaler::DIV2;
        config.rcc.apb1_pre = APBPrescaler::DIV2;
        config.rcc.apb2_pre = APBPrescaler::DIV2;
        config.rcc.apb3_pre = APBPrescaler::DIV2;
        config.rcc.apb4_pre = APBPrescaler::DIV2;
        config.rcc.voltage_scale = VoltageScale::Scale1;
    }
    config
}
